import type { SpriteData, MonsterId, TileId } from './types';

/** Horizontally mirror a sprite (derives left-facing from right-facing). */
function mirror(s: SpriteData): SpriteData {
  return {
    w: s.w,
    h: s.h,
    palette: s.palette,
    rows: s.rows.map((r) => r.split('').reverse().join('')),
  };
}

